<template><div class="page">
<v-card flat class="hero pa-5 mb-4"><div class="d-flex align-center"><div><div class="text-overline">SYSTEM</div><h1 class="text-h5 font-weight-bold">Company Profile & Settings</h1><div class="grey--text">Manage ZeeraK business identity and application preferences.</div></div><v-spacer/><v-btn v-if="$can('settings.edit')" color="#165134" dark @click="saveCompany"><v-icon left>mdi-content-save</v-icon>Save</v-btn></div></v-card>
<v-row><v-col cols="12" md="8"><v-card outlined><v-card-title>Company Information</v-card-title><v-card-text><v-row><v-col cols="12" md="6"><v-text-field v-model="form.company_name" label="Company Name *" outlined dense/></v-col><v-col cols="12" md="6"><v-text-field v-model="form.legal_name" label="Legal / Registered Name" outlined dense/></v-col><v-col cols="12" md="6"><v-text-field v-model="form.phone" label="Phone" outlined dense/></v-col><v-col cols="12" md="6"><v-text-field v-model="form.whatsapp" label="WhatsApp" outlined dense/></v-col><v-col cols="12" md="6"><v-text-field v-model="form.email" label="Email" outlined dense/></v-col><v-col cols="12" md="6"><v-text-field v-model="form.website" label="Website" outlined dense/></v-col><v-col cols="12" md="6"><v-text-field v-model="form.city" label="City" outlined dense/></v-col><v-col cols="12" md="3"><v-text-field v-model="form.ntn" label="NTN" outlined dense/></v-col><v-col cols="12" md="3"><v-select v-model="form.currency" :items="['PKR','USD','AED','SAR']" label="Currency" outlined dense/></v-col><v-col cols="12"><v-textarea v-model="form.address" label="Office Address" outlined dense rows="2"/></v-col><v-col cols="12"><v-textarea v-model="form.receipt_footer" label="Receipt / Statement Footer" outlined dense rows="2"/></v-col></v-row></v-card-text></v-card></v-col>
<v-col cols="12" md="4"><v-card outlined class="mb-4"><v-card-title>Branding</v-card-title><v-card-text class="text-center"><v-img :src="form.logo_url||'/images/zeerak-logo.jpeg'" contain max-height="150" class="mb-4"/><v-file-input v-if="$can('settings.edit')" v-model="logo" accept="image/png,image/jpeg,image/webp" label="Change logo" outlined dense/><v-btn v-if="$can('settings.edit')" block color="#165134" dark :disabled="!logo" @click="saveLogo">Upload Logo</v-btn></v-card-text></v-card>
<v-card outlined><v-card-title>Interface Preferences</v-card-title><v-card-text><v-switch v-model="dark" label="Dark mode" color="#165134" @change="saveInterface"/><v-switch v-model="compact" label="Compact navigation" color="#165134" @change="saveInterface"/></v-card-text></v-card></v-col></v-row></div></template>
<script>
import api from '../../../services/api'
export default{name:'Settings',data(){return{loading:false,saving:false,logoSaving:false,logo:null,dark:localStorage.getItem('zeerak_dark_mode')==='1',compact:localStorage.getItem('zeerak_compact_nav')==='1',form:{company_name:'',legal_name:'',phone:'',whatsapp:'',email:'',website:'',address:'',city:'',ntn:'',currency:'PKR',receipt_footer:'',logo_url:''}}},mounted(){this.loadCompany()},methods:{async loadCompany(){this.loading=true;try{const r=await api.get('/company-settings');this.form=Object.assign(this.form,r.data)}catch(e){this.message('Unable to load company settings.','error')}finally{this.loading=false}},async saveCompany(){this.saving=true;try{const payload=Object.assign({},this.form);delete payload.logo_url;delete payload.logo_path;delete payload.id;delete payload.created_at;delete payload.updated_at;const r=await api.put('/company-settings',payload);this.form=Object.assign(this.form,r.data.settings);this.message('Company settings saved.','success')}catch(e){this.message((e.response&&e.response.data&&e.response.data.message)||'Unable to save settings.','error')}finally{this.saving=false}},async saveLogo(){if(!this.logo)return;this.logoSaving=true;try{const fd=new FormData();fd.append('logo',this.logo);const r=await api.post('/company-settings/logo',fd,{headers:{'Content-Type':'multipart/form-data'}});this.form=Object.assign(this.form,r.data.settings);this.logo=null;this.message('Company logo updated.','success')}catch(e){this.message('Unable to upload logo.','error')}finally{this.logoSaving=false}},saveInterface(){localStorage.setItem('zeerak_dark_mode',this.dark?'1':'0');localStorage.setItem('zeerak_compact_nav',this.compact?'1':'0');this.$vuetify.theme.dark=this.dark;document.documentElement.setAttribute('data-theme',this.dark?'dark':'light');this.$root.$emit('theme-changed',this.dark)},message(t,c){this.$root.$emit(c==='error'?'show-error':c==='warning'?'show-warning':c==='info'?'show-info':'show-success',t)}}}
</script><style scoped>.page{width:100%}.hero{border-left:4px solid #165134}</style>